package org.transittr;
import android.content.*;import java.io.*;import java.util.*;import org.json.*;
/** Scans compressed APK records; no database copy or expanded index is written to storage. */
public final class StreamCatalog {
 private final Context context;private final SharedPreferences prefs;private static JSONObject metadata;
 public StreamCatalog(Context c){context=c.getApplicationContext();prefs=c.getSharedPreferences("MainActivity",0);}
 private DataInputStream input(int city)throws IOException{return new DataInputStream(new BufferedInputStream(new java.util.zip.GZIPInputStream(context.getAssets().open("catalog-stream-"+city+".dbz"),8192),8192));}
 private static String text(DataInputStream in)throws IOException{int n=in.readUnsignedShort();byte[] b=new byte[n];in.readFully(b);return new String(b,"UTF-8");}
 private static int[] header(DataInputStream in)throws IOException{if(in.readInt()!=0x54524331)throw new IOException("Katalog sürümü geçersiz");return new int[]{in.readInt(),in.readInt()};}
 private static CatalogStore.Item record(DataInputStream in,int kind)throws IOException{CatalogStore.Item r=new CatalogStore.Item();r.id=in.readInt();r.kind=kind;r.code=text(in);r.name=text(in);if(kind==0)r.type=text(in);else{r.type="Durak";r.lat=in.readDouble();r.lon=in.readDouble();}r.source=in.readInt();return r;}
 private interface Visitor{void item(CatalogStore.Item r);}
 private static void skip(DataInputStream in,int size)throws IOException{while(size>0){int n=in.skipBytes(size);if(n==0){if(in.read()==-1)throw new EOFException();n=1;}size-=n;}}
 private static void skipText(DataInputStream in)throws IOException{skip(in,in.readUnsignedShort());}
 private static void skipRecord(DataInputStream in,int kind)throws IOException{in.readInt();skipText(in);skipText(in);if(kind==0)skipText(in);else skip(in,16);in.readInt();}
 private int[] scan(int city,Visitor v)throws IOException{return scan(city,v,-1);}
 private int[] scan(int city,Visitor v,int selectedKind)throws IOException{DataInputStream in=input(city);try{int[] counts=header(in);for(int kind=0;kind<2;kind++)for(int i=0;i<counts[kind];i++){if(selectedKind>=0&&kind!=selectedKind)skipRecord(in,kind);else v.item(record(in,kind));}return counts;}finally{in.close();}}
 public HashMap<String,CatalogStore.Item> stops(int city,final HashSet<String> codes)throws IOException{final HashMap<String,CatalogStore.Item> found=new HashMap<String,CatalogStore.Item>();scan(city,new Visitor(){public void item(CatalogStore.Item r){if(codes.contains(r.code)&&!found.containsKey(r.code))found.put(r.code,r);}},1);return found;}
 public CatalogStore.Page page(final int city,final int mode,String query,final int offset)throws IOException{
  final String q=CatalogStore.normalize(query.trim());final CatalogStore.Page p=new CatalogStore.Page();final ArrayList<CatalogStore.Item> exact=new ArrayList<CatalogStore.Item>(),others=new ArrayList<CatalogStore.Item>();final int keep=Math.max(0,offset)+50;
  int[] counts=scan(city,new Visitor(){public void item(CatalogStore.Item r){if(mode<2&&r.kind!=mode||mode==2&&!prefs.getBoolean("fav:"+r.kind+":"+r.id,false))return;if(!CatalogStore.normalize(r.code+" "+r.name).contains(q))return;p.total++;ArrayList<CatalogStore.Item> a=CatalogStore.normalize(r.code).equals(q)?exact:others;if(a.size()<keep)a.add(r);}},mode==2?-1:mode);p.routes=counts[0];p.stops=counts[1];exact.addAll(others);for(int i=Math.max(0,offset);i<Math.min(exact.size(),offset+50);i++)p.items.add(exact.get(i));return p;
 }
 public CatalogStore.Item stop(int city,final String code,final boolean suffix)throws IOException{final ArrayList<CatalogStore.Item> found=new ArrayList<CatalogStore.Item>();scan(city,new Visitor(){public void item(CatalogStore.Item r){if(r.kind==1&&(suffix?r.code.matches(java.util.regex.Pattern.quote(code)+"[a-zA-Z]"):r.code.equals(code))&&found.size()<2)found.add(r);}});return found.size()==1?found.get(0):null;}
 public CatalogStore.Page nearby(int city,final double lat,final double lon)throws IOException{if(Double.isNaN(lat)||Double.isNaN(lon)||Math.abs(lat)>90||Math.abs(lon)>180)throw new IOException("Geçerli koordinat gir");final CatalogStore.Page p=new CatalogStore.Page();int[] counts=scan(city,new Visitor(){public void item(CatalogStore.Item r){if(r.kind!=1||!r.hasPosition())return;double a=Math.PI/180,x=Math.sin((r.lat-lat)*a/2),y=Math.sin((r.lon-lon)*a/2);r.distance=12742000*Math.asin(Math.sqrt(Math.min(1,x*x+Math.cos(lat*a)*Math.cos(r.lat*a)*y*y)));if(r.distance<=2000)p.items.add(r);}});p.routes=counts[0];p.stops=counts[1];Collections.sort(p.items,new Comparator<CatalogStore.Item>(){public int compare(CatalogStore.Item a,CatalogStore.Item b){return Double.compare(a.distance,b.distance);}});p.total=p.items.size();while(p.items.size()>50)p.items.remove(p.items.size()-1);return p;}
 private static class Link{int city;String external="";ArrayList<Integer> ids=new ArrayList<Integer>();}
 private Link link(int id)throws IOException{DataInputStream in=new DataInputStream(new BufferedInputStream(new java.util.zip.GZIPInputStream(context.getAssets().open("catalog-links.dbz")),8192));try{int n=in.readInt();for(int i=0;i<n;i++){int route=in.readInt(),city=in.readInt();String ext=text(in);int count=in.readInt();if(route==id){Link l=new Link();l.city=city;l.external=ext;for(int k=0;k<count;k++)l.ids.add(Integer.valueOf(in.readInt()));return l;}for(int k=0;k<count;k++)in.readInt();}return null;}finally{in.close();}}
 public String external(int route)throws IOException{Link l=link(route);return l==null?"":l.external;}
 public ArrayList<CatalogStore.Item> routeStops(int route)throws IOException{Link l=link(route);ArrayList<CatalogStore.Item> out=new ArrayList<CatalogStore.Item>();if(l==null)return out;final HashSet<Integer> wanted=new HashSet<Integer>(l.ids);final HashMap<Integer,CatalogStore.Item> found=new HashMap<Integer,CatalogStore.Item>();scan(l.city,new Visitor(){public void item(CatalogStore.Item r){if(r.kind==1&&wanted.contains(Integer.valueOf(r.id)))found.put(Integer.valueOf(r.id),r);}});for(Integer id:l.ids){CatalogStore.Item r=found.get(id);if(r!=null)out.add(r);}return out;}
 private synchronized JSONObject metadata()throws IOException{if(metadata!=null)return metadata;InputStream in=context.getAssets().open("catalog-meta.json");try{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>524288)throw new IOException("Katalog bilgi sınırı");out.write(b,0,n);}try{metadata=new JSONObject(new String(out.toByteArray(),"UTF-8"));return metadata;}catch(JSONException e){throw new IOException("Katalog bilgisi okunamadı");}}finally{in.close();}}
 public String source(int id)throws IOException{try{JSONArray a=metadata().getJSONArray("sources");for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);if(r.getInt("id")==id)return r.optString("name")+"\n"+r.optString("url")+"\n"+r.optString("license")+"\nYerel veri anlık hizmet durumunu göstermez.";}return id==100?"Kentkart ulaşım servisi":id==101?"ASİS ulaşım servisi":"";}catch(JSONException e){throw new IOException("Kaynak bilgisi okunamadı");}}
 public String schedule(int stop)throws IOException{try{JSONArray rows=CompactData.read(context,"stop-times",stop),services=metadata().getJSONArray("services"),exceptions=metadata().getJSONArray("exceptions");final HashSet<Integer> wanted=new HashSet<Integer>();for(int i=0;i<rows.length();i++)wanted.add(Integer.valueOf(rows.getJSONArray(i).getInt(0)));final HashMap<Integer,String> labels=new HashMap<Integer,String>();for(int city:new int[]{0,1,2,6})scan(city,new Visitor(){public void item(CatalogStore.Item r){if(r.kind==0&&wanted.contains(Integer.valueOf(r.id)))labels.put(Integer.valueOf(r.id),r.code+" · "+r.name);}});
  Calendar now=Calendar.getInstance(TimeZone.getTimeZone("GMT+03:00"));int sec=now.get(Calendar.HOUR_OF_DAY)*3600+now.get(Calendar.MINUTE)*60+now.get(Calendar.SECOND);ArrayList<String> ordered=new ArrayList<String>();for(int offset=-1;offset<=1;offset++){Calendar day=(Calendar)now.clone();day.add(Calendar.DATE,offset);String date=String.format(Locale.US,"%04d%02d%02d",day.get(Calendar.YEAR),day.get(Calendar.MONTH)+1,day.get(Calendar.DAY_OF_MONTH));int bit=1<<((day.get(Calendar.DAY_OF_WEEK)+5)%7);HashMap<String,Boolean> active=new HashMap<String,Boolean>();for(int i=0;i<services.length();i++){JSONObject s=services.getJSONObject(i);active.put(s.getString("id"),Boolean.valueOf(s.getString("start").compareTo(date)<=0&&s.getString("end").compareTo(date)>=0&&(s.getInt("mask")&bit)!=0));}for(int i=0;i<exceptions.length();i++){JSONObject e=exceptions.getJSONObject(i);if(date.equals(e.getString("date")))active.put(e.getString("service"),Boolean.valueOf(e.getInt("type")==1));}for(int i=0;i<rows.length();i++){JSONArray r=rows.getJSONArray(i);int t=r.getInt(2),delta=t+offset*86400-sec;if(delta<0||delta>=86400||!Boolean.TRUE.equals(active.get(r.getString(1))))continue;ordered.add(String.format(Locale.US,"%05d|%02d:%02d · %s",delta,(t/3600)%24,(t/60)%60,labels.get(Integer.valueOf(r.getInt(0)))));}}
  Collections.sort(ordered);StringBuilder text=new StringBuilder("Planlı kalkışlar · Türkiye saati\nCanlı varış değildir.\n");for(int i=0;i<ordered.size()&&i<8;i++)text.append(ordered.get(i).substring(6)).append('\n');if(ordered.isEmpty())text.append("Önümüzdeki 24 saat için geçerli tarife kaydı yok.");return text.toString();
 }catch(JSONException e){throw new IOException("Tarife okunamadı");}}
}
